  });
  document.addEventListener('keydown', function (ev) {
    if (ev.key === 'Escape' && state.modal) {
      state.modal = null;
      render();
    }
  });

  /* ---------- 启动：同步渲染，页面加载即就绪（无加载态） ---------- */
  initSteps();
  seedLog();
  render();
  setInterval(tickCountdowns, 1000);
})();

