396	        '<span class="check-text">' + esc(c.text) + '<em>预期：' + esc(c.expect) + '</em></span></label>';
397	    });
398	    html += '</div></section>';
399	
400	    html += '<section class="detail-sec"><details class="contingency">' +
401	      '<summary>异常处置 · 若结果与预期不符</summary>' +
402	      '<p class="cont-trigger">触发条件：' + esc(s.contingency.trigger) + '</p><ol>';
403	    s.contingency.steps.forEach(function (x) { html += '<li>' + esc(x) + '</li>'; });
404	    html += '</ol>' + (s.contingency.note ? '<p class="muted">' + esc(s.contingency.note) + '</p>' : '') +
405	      '</details></section>';
406	
407	    if (active) {
408	      html += '<div class="detail-actions">' +
409	        '<button type="button" class="btn ' + (s.irreversible ? 'btn-danger' : 'btn-primary') +
410	        '" data-action="submit-step" data-step="' + s.id + '">' +
411	        (s.irreversible ? '进入执行确认…' : '确认完成本步骤') + '</button>' +
412	        (s.irreversible
413	          ? '<span class="action-hint">将弹出确认对话框，需输入确认码 <b>' + s.confirmCode + '</b> 后才会执行；执行后可随时启动恢复路径</span>'
414	          : '<span class="action-hint">本步骤可逆：' + esc(s.fallback || '重跑本步骤即可。') + '</span>') +
415	        '</div>';
416	    } else if (s.status === 'done' && s.irreversible) {
417	      html += '<div class="detail-actions">' +
418	        '<button type="button" class="btn btn-ghost" data-action="start-recovery" data-step="' + s.id + '">' +
419	        '<svg class="ic"><use href="#i-undo"/></svg> 启动恢复路径</button>' +
420	        '<span class="action-hint">恢复将回滚本步骤并重新锁定其后步骤（恢复确认码 ' + RECOVERY_CODE + '）</span></div>';
421	    }
