424	  }
425	  function completionHtml() {
426	    function stat(label, value) {
427	      return '<div class="stat"><span class="stat-v">' + value + '</span><span class="stat-k">' + label + '</span></div>';
428	    }
429	    var g = state.intercepts;
430	    var html = '<div class="completion">' +
431	      '<div class="cert-banner"><svg class="ic big"><use href="#i-check"/></svg><div>' +
