528	        '<h3 id="mTitle">' + esc(s.title) + ' 的回滚程序</h3>' +
529	        '<p class="muted">' + esc(s.recovery.summary) + '</p>' +
530	        '<div class="modal-sec"><h4>恢复检查项 <span class="muted" id="recCount">' + recDoneCount(m) + '/' + s.recovery.steps.length + '</span></h4><div class="check-list">';
531	      s.recovery.steps.forEach(function (x, i) {
532	        var on = !!m.checked[i];
533	        html += '<label class="check-item' + (on ? ' on' : '') + '">' +
534	          '<input type="checkbox" data-action="toggle-rec" data-idx="' + i + '"' + (on ? ' checked' : '') + '/>' +
535	          '<span class="check-box" aria-hidden="true"><svg class="ic"><use href="#i-check"/></svg></span>' +
536	          '<span class="check-text">' + esc(x) + '</span></label>';
537	      });
538	      html += '</div></div>' +
539	        '<div class="modal-sec"><h4>输入恢复确认码 <b>' + RECOVERY_CODE + '</b> 以执行回滚</h4>' +
540	        '<input id="recoveryCode" class="code-input" autocomplete="off" spellcheck="false" placeholder="RECOVER"/>' +
541	        errHtml(m) + '</div>' +
542	        '<div class="modal-actions">' +
543	        '<button type="button" class="btn btn-ghost" data-action="close-modal">取消恢复</button>' +
544	        '<button type="submit" class="btn btn-primary">完成恢复</button></div></form>';
545	    } else {
546	      html = '<form class="modal" role="dialog" aria-modal="true" aria-labelledby="mTitle">' +
547	        '<h3 id="mTitle">重新开始演练？</h3>' +
548	        '<p class="muted">将清空当前执行进度、执行日志与拦截记录，回到第 1 步。</p>' +
549	        '<div class="modal-actions">' +
550	        '<button type="button" class="btn btn-ghost" data-action="close-modal">继续当前演练</button>' +
551	        '<button type="submit" class="btn btn-danger">确认重新开始</button></div></form>';
552	    }
553	    root.hidden = false;
554	    root.innerHTML = html;
555	  }
556	  function focusModalInput() {
557	    var el = byId('confirmCode') || byId('recoveryCode');
558	    if (el) el.focus();
559	  }
560	  function tickCountdowns() {
561	    var els = document.querySelectorAll('[data-cd]');
562	    if (!els.length) return;
563	    var nowMs = Date.now();
564	    els.forEach(function (el) {
565	      var s = stepById(el.getAttribute('data-cd'));
566	      if (!s || !s.deadline) { el.textContent = '--:--'; return; }
567	      var rem = s.deadline - nowMs;
568	      el.textContent = rem > 0 ? fmtRemaining(rem) : '已超窗';
569	    });
570	  }
571	
572	  /* ---------- 事件委托 ---------- */
573	  document.addEventListener('click', function (ev) {
574	    var el = ev.target.closest ? ev.target.closest('[data-action]') : null;
575	    if (!el) return;
