577	    if (act === 'select-step') selectStep(el.getAttribute('data-step'));
578	    else if (act === 'submit-step') submitStep(el.getAttribute('data-step'));
579	    else if (act === 'start-recovery') startRecovery(el.getAttribute('data-step'));
580	    else if (act === 'close-modal') { state.modal = null; render(); }
581	    else if (act === 'restart') { state.modal = { type: 'restart', stepId: null, error: null }; render(); }
582	    else if (act === 'export-log') exportLog();
583	    else if (act === 'copy-log') copyLog();
584	  });
585	  document.addEventListener('change', function (ev) {
