591	    var r = ev.target.closest ? ev.target.closest('[data-action="toggle-rec"]') : null;
592	    if (r && state.modal) {
593	      var i = Number(r.getAttribute('data-idx'));
594	      if (r.checked) state.modal.checked[i] = true; else delete state.modal.checked[i];
595	      clearGuard();
596	      var cnt = byId('recCount');
597	      var s = stepById(state.modal.stepId);
598	      if (cnt && s) cnt.textContent = recDoneCount(state.modal) + '/' + s.recovery.steps.length;
599	    }
