605	    if (form.querySelector('#confirmCode')) confirmExecute();
606	    else if (form.querySelector('#recoveryCode')) completeRecovery();
607	    else restartRun();
608	  });
609	  document.addEventListener('keydown', function (ev) {
610	    if (ev.key === 'Escape' && state.modal) {
611	      state.modal = null;
612	      render();
613	    }
614	  });
615	
616	  /* ---------- 启动：同步渲染，页面加载即就绪（无加载态） ---------- */
617	  initSteps();
