/* 切换指挥台 · 样式（spacious 低密度；层级：中栏执行卡 dominant > 左导航/右检查器 primary > 日志 supporting） */
:root {
  --bg: #eef1f5;
  --panel: #ffffff;
  --border: #dde3ea;
  --ink: #1a2532;
  --ink-2: #55657a;
  --ink-3: #8a97a6;
  --accent: #2563eb;
  --accent-deep: #1d4ed8;
  --accent-soft: #e9efff;
  --accent-line: #c3d4fb;
  --good: #0a7d43;
  --good-soft: #e5f5ec;
  --warn: #b45309;
  --warn-soft: #fdf3e3;
  --warn-line: #f0d5ad;
  --danger: #d92d20;
  --danger-soft: #fdeceb;
  --lock: #98a4b3;
  --recov: #6941c6;
  --recov-soft: #f1ecfc;
  --header-bg: #0e1e33;
  --header-ink: #e8eef7;
  --radius: 10px;
  --shadow: 0 1px 2px rgba(16, 24, 40, .05), 0 1px 3px rgba(16, 24, 40, .08);
  --font: "Segoe UI", "Microsoft YaHei", "PingFang SC", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: var(--font);
  font-size: 14px;
  color: var(--ink);
  background: var(--bg);
  overflow: hidden;
}
button { font-family: inherit; }
.muted { color: var(--ink-3); font-size: 12px; }
.ic { width: 15px; height: 15px; flex: none; vertical-align: -2px; }
.ic.big { width: 22px; height: 22px; }
.ic-warn { color: var(--warn); }

/* 加载态：仅作为结构上的状态钩子保留；本应用数据内联、同步渲染，永不进入该状态 */
.app[data-loading="true"]::after {
  content: "加载中…";
  position: fixed; inset: 0; z-index: 99;
  display: grid; place-items: center;
  background: var(--bg); color: var(--ink-3);
}

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }

/* ---------- 头部 ---------- */
.header {
  height: 60px; flex: none;
  display: flex; align-items: center; gap: 18px;
  padding: 0 18px;
  background: var(--header-bg); color: var(--header-ink);
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 8px;
  display: grid; place-items: center;
  background: linear-gradient(135deg, #2e6bff, #14406e);
  color: #fff; font-weight: 700; font-size: 16px;
}
.brand-text { display: flex; flex-direction: column; line-height: 1.25; }
.brand-text strong { font-size: 15px; letter-spacing: .5px; }
.brand-text span { font-size: 11px; color: #9db1cc; }
.wf-meta { display: flex; align-items: center; gap: 10px; min-width: 0; }
.wf-title { font-size: 14px; font-weight: 600; white-space: nowrap; }
.header-status { margin-left: auto; display: flex; align-items: center; gap: 12px; }

.chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 9px; border-radius: 999px;
  font-size: 12px; font-weight: 600; white-space: nowrap;
}
.chip-dark { background: rgba(255, 255, 255, .12); color: #cfe0f5; font-family: Consolas, monospace; }
.chip-env { background: rgba(255, 255, 255, .10); color: #9db1cc; font-weight: 500; }
.chip-guard { background: rgba(255, 255, 255, .10); color: #cfe0f5; }
.chip-guard.hot { background: #fda29b; color: #7a1207; }
.chip-phase { background: var(--accent-soft); color: var(--accent-deep); }
.chip-irrev { background: var(--warn-soft); color: var(--warn); border: 1px solid var(--warn-line); }
.chip-rev { background: var(--good-soft); color: var(--good); }

.progress { display: flex; align-items: center; gap: 8px; }
.progress-bar {
  width: 150px; height: 8px; border-radius: 999px;
  background: rgba(255, 255, 255, .16); overflow: hidden;
}
.progress-bar i {
  display: block; height: 100%; width: 0;
  background: linear-gradient(90deg, #4c8dff, #7db0ff);
  border-radius: 999px; transition: width .35s ease;
}
.progress-text { font-size: 12px; color: #cfe0f5; font-variant-numeric: tabular-nums; }

/* ---------- 主区三栏 ---------- */
.app { height: 100vh; display: flex; flex-direction: column; }
.main {
  flex: 1; min-height: 0;
  display: grid; gap: 14px; padding: 14px;
  grid-template-columns: minmax(250px, 300px) minmax(0, 1fr) minmax(310px, 370px);
  max-width: 1680px; margin: 0 auto; width: 100%;
}
.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.step-nav, .step-detail, .inspector, .run-log { overflow-y: auto; min-height: 0; }
.right-col { display: flex; flex-direction: column; gap: 14px; min-height: 0; }
.inspector { flex: 1.35; }
.run-log { flex: 1; display: flex; flex-direction: column; }

/* ---------- 左：阶段/步骤导航 ---------- */
.step-nav { padding: 12px; }
.nav-phase { margin-bottom: 14px; }
.nav-phase-name {
  font-size: 11px; font-weight: 700; letter-spacing: 1px;
  color: var(--ink-3); text-transform: uppercase;
  padding: 4px 6px 8px;
}
.nav-step {
  display: flex; align-items: center; gap: 9px; width: 100%;
  padding: 9px 10px; margin-bottom: 4px;
  background: none; border: 1px solid transparent; border-radius: 8px;
  font-size: 13px; color: var(--ink); text-align: left; cursor: pointer;
}
.nav-step:hover { background: #f4f7fb; }
.nav-step.selected { background: var(--accent-soft); border-color: var(--accent-line); }
.nav-step .ico {
  width: 20px; height: 20px; flex: none; border-radius: 50%;
  display: grid; place-items: center; font-size: 11px; font-weight: 700;
}
.nav-step .ico .ic { width: 12px; height: 12px; }
.nav-step.done .ico { background: var(--good); color: #fff; }
.nav-step.ready .ico { background: #fff; border: 2px solid var(--accent); color: var(--accent); }
.nav-step.locked { color: var(--ink-3); cursor: not-allowed; }
.nav-step.locked .ico { background: #eef1f4; color: var(--lock); }
.nav-body { flex: 1; min-width: 0; line-height: 1.35; }
.nav-code { font-family: Consolas, monospace; font-size: 11px; color: var(--ink-3); margin-right: 4px; }
.nav-step.selected .nav-code { color: var(--accent-deep); }
.nav-recov {
  display: inline-block; margin-left: 6px; padding: 0 5px;
  font-size: 10px; border-radius: 4px;
  background: var(--recov-soft); color: var(--recov);
}

/* ---------- 中：步骤执行卡（dominant） ---------- */
.step-detail { padding: 22px 26px 28px; }
.guard-banner {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 14px; padding: 10px 14px;
  background: var(--danger-soft); color: #912018;
  border: 1px solid #f4b3ad; border-radius: 8px;
  font-size: 13px; font-weight: 600;
  animation: shake .3s ease;
}
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  30% { transform: translateX(-4px); }
  60% { transform: translateX(4px); }
}
.detail-kicker { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.step-code { font-family: Consolas, monospace; font-size: 12px; color: var(--ink-3); }
.detail-title { font-size: 22px; font-weight: 700; letter-spacing: .3px; margin-bottom: 8px; }
.detail-goal { color: var(--ink-2); margin-bottom: 18px; line-height: 1.6; }

.exec-stamp {
  display: flex; align-items: center; gap: 7px;
  margin-bottom: 16px; padding: 9px 14px;
  background: var(--good-soft); color: var(--good);
  border-radius: 8px; font-weight: 600; font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.exec-stamp strong { font-variant-numeric: tabular-nums; }
.lock-stamp {
  display: flex; align-items: center; gap: 7px;
  margin-bottom: 16px; padding: 9px 14px;
  background: #f2f4f7; color: var(--ink-3);
  border-radius: 8px; font-size: 13px;
}

.detail-sec { margin-top: 20px; }
.detail-sec h3 {
  font-size: 12px; font-weight: 700; letter-spacing: 1px;
  color: var(--ink-3); text-transform: uppercase; margin-bottom: 10px;
}
.action-list { padding-left: 20px; color: var(--ink-2); line-height: 1.9; }

.check-list { display: flex; flex-direction: column; gap: 8px; }
.check-item {
  display: flex; align-items: flex-start; gap: 11px;
  padding: 12px 14px; border: 1px solid var(--border); border-radius: 8px;
  cursor: pointer; transition: background .15s, border-color .15s;
}
.check-item:hover { background: #f7fafd; }
.check-item input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.check-box {
  width: 19px; height: 19px; flex: none; margin-top: 1px;
  border: 2px solid #b6c2d0; border-radius: 5px;
  display: grid; place-items: center; color: #fff; background: #fff;
  transition: background .12s, border-color .12s;
}
.check-box .ic { width: 12px; height: 12px; opacity: 0; }
.check-item input:focus-visible + .check-box { outline: 2px solid var(--accent); outline-offset: 2px; }
.check-item.on { background: #f4faf6; border-color: #b7dfc6; }
.check-item.on .check-box { background: var(--good); border-color: var(--good); }
.check-item.on .check-box .ic { opacity: 1; }
.check-text { line-height: 1.5; font-weight: 600; }
.check-text em { display: block; margin-top: 3px; font-style: normal; font-weight: 400; font-size: 12px; color: var(--ink-3); }
.check-item.ro { cursor: default; opacity: .85; }

.contingency {
  border: 1px dashed var(--border); border-radius: 8px;
  padding: 12px 16px; color: var(--ink-2);
}
.contingency summary {
  cursor: pointer; font-weight: 600; color: var(--ink);
  font-size: 13px; user-select: none;
}
.contingency ol { padding-left: 20px; margin: 10px 0; line-height: 1.9; }
.cont-trigger { margin-top: 8px; font-size: 12px; color: var(--warn); }

.detail-actions {
  display: flex; align-items: center; gap: 14px;
  margin-top: 26px; padding-top: 18px;
  border-top: 1px solid var(--border);
}
.action-hint { font-size: 12px; color: var(--ink-3); line-height: 1.5; }
.action-hint b { color: var(--warn); font-family: Consolas, monospace; }

/* ---------- 按钮 ---------- */
.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 9px 18px; border-radius: 8px; border: none;
  font-size: 13px; font-weight: 600; cursor: pointer;
  transition: filter .15s, background .15s;
}
.btn:hover { filter: brightness(1.05); }
.btn:disabled { cursor: not-allowed; opacity: .5; filter: none; }
.btn-primary { background: var(--accent); color: #fff; }
.btn-danger { background: var(--danger); color: #fff; }
.btn-ghost { background: #fff; color: var(--ink-2); border: 1px solid var(--border); }
.header .btn-ghost { background: rgba(255, 255, 255, .08); border-color: rgba(255, 255, 255, .2); color: #cfe0f5; }
.btn-dim { opacity: .55; }
.btn-sm { padding: 6px 12px; font-size: 12px; }
.btn-xs { padding: 3px 9px; font-size: 11px; border-radius: 6px; }

/* ---------- 右：风险与恢复检查器 ---------- */
.inspector { padding: 16px 18px; }
.insp-head {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding-bottom: 12px; margin-bottom: 14px;
  border-bottom: 1px solid var(--border);
}
.insp-head h3 { font-size: 13px; font-weight: 700; }
.insp-sec { margin-bottom: 16px; }
.insp-sec h4 {
  font-size: 11px; font-weight: 700; letter-spacing: 1px;
  color: var(--ink-3); text-transform: uppercase; margin-bottom: 6px;
}
.insp-sec p { font-size: 13px; line-height: 1.65; color: var(--ink-2); }
.insp-recovery {
  background: var(--warn-soft); border: 1px solid var(--warn-line);
  border-radius: 8px; padding: 12px 14px;
}
.insp-recovery h4 { color: var(--warn); }
.insp-recovery ol { padding-left: 18px; margin: 4px 0 8px; }
.insp-recovery li { font-size: 12.5px; line-height: 1.8; color: #6d4407; }
.insp-recovery .muted { color: #a1753a; }
.insp-cd { margin-top: 10px; font-size: 12px; color: var(--ink-2); font-variant-numeric: tabular-nums; }
.insp-cd strong { color: var(--recov); font-size: 14px; }

/* ---------- 右：执行日志 ---------- */
.run-log { padding: 0; }
.log-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 14px; border-bottom: 1px solid var(--border);
  position: sticky; top: 0; background: var(--panel);
}
.log-head h3 { font-size: 13px; font-weight: 700; }
.log-tools { display: flex; gap: 6px; }
.log-list { list-style: none; padding: 8px 12px; font-size: 12px; }
.log-list li {
  padding: 7px 9px; margin-bottom: 4px; border-radius: 6px;
  line-height: 1.5; color: var(--ink-2); background: #f7f9fb;
}
.log-list .lt {
  font-family: Consolas, monospace; font-size: 11px;
  color: var(--ink-3); margin-right: 6px; font-variant-numeric: tabular-nums;
}
.log-guard { background: var(--danger-soft) !important; color: #912018 !important; }
.log-confirm { background: var(--accent-soft) !important; color: var(--accent-deep) !important; }
.log-recovery { background: var(--recov-soft) !important; color: var(--recov) !important; }
.log-action { background: #eef4ff !important; }
.log-done { background: var(--good-soft) !important; color: var(--good) !important; }
.log-empty { color: var(--ink-3); text-align: center; padding: 18px 0; }

/* ---------- 完成凭证 ---------- */
.completion { padding: 8px 2px; }
.cert-banner {
  display: flex; align-items: center; gap: 16px;
  padding: 22px 24px; border-radius: 12px;
  background: linear-gradient(120deg, #067647, #0a9159);
  color: #fff; box-shadow: var(--shadow);
}
.cert-banner h2 { font-size: 24px; letter-spacing: 1px; }
.cert-banner p { margin-top: 6px; opacity: .92; font-size: 13px; }
.cert-stats { display: flex; gap: 10px; margin: 18px 0 6px; flex-wrap: wrap; }
.stat {
  flex: 1; min-width: 108px;
  background: #f7f9fc; border: 1px solid var(--border); border-radius: 10px;
  padding: 14px 16px; display: flex; flex-direction: column; gap: 4px;
}
.stat-v { font-size: 20px; font-weight: 700; font-variant-numeric: tabular-nums; }
.stat-k { font-size: 12px; color: var(--ink-3); }
.guard-list { list-style: none; }
.guard-list li {
  padding: 8px 12px; margin-bottom: 6px; border-radius: 6px;
  background: var(--danger-soft); color: #912018; font-size: 12.5px; line-height: 1.5;
}
.empty-state {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  padding: 26px; border: 1px dashed var(--border); border-radius: 8px;
  color: var(--ink-3); font-size: 13px;
}
.empty-state .ic { color: var(--good); }

/* ---------- 模态（确认 / 恢复 / 重开） ---------- */
.modal-root {
  position: fixed; inset: 0; z-index: 50;
  display: grid; place-items: center;
  background: rgba(10, 18, 30, .48);
}
.modal {
  width: min(580px, 94vw); max-height: 88vh; overflow-y: auto;
  background: #fff; border-radius: 14px; padding: 24px 26px;
  box-shadow: 0 24px 64px rgba(2, 12, 27, .38);
}
.modal h3 { font-size: 18px; margin-bottom: 12px; }
.modal-flag {
  display: flex; align-items: center; gap: 8px;
  margin: -24px -26px 16px; padding: 12px 26px;
  background: var(--danger); color: #fff;
  border-radius: 14px 14px 0 0; font-weight: 700; font-size: 14px;
}
.modal-flag-recov { background: var(--recov); }
.modal-sec { margin-top: 16px; }
.modal-sec h4 { font-size: 12px; font-weight: 700; color: var(--ink-3); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 8px; }
.modal-sec h4 b { color: var(--warn); font-family: Consolas, monospace; font-size: 13px; }
.modal-sec > p { font-size: 13.5px; line-height: 1.7; color: var(--ink-2); }
.modal-recovery {
  background: var(--warn-soft); border: 1px solid var(--warn-line);
  border-radius: 8px; padding: 12px 14px;
}
.modal-recovery h4 { color: var(--warn); }
.modal-recovery ol { padding-left: 18px; margin: 4px 0 6px; }
.modal-recovery li { font-size: 12.5px; line-height: 1.8; color: #6d4407; }
.modal-recovery .muted { color: #a1753a; }
.code-input {
  width: 100%; margin-top: 4px; padding: 11px 14px;
  font-family: Consolas, monospace; font-size: 15px; letter-spacing: 1px;
  border: 1.5px solid var(--border); border-radius: 8px;
}
.code-input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.field-error {
  margin-top: 8px; padding: 8px 12px; border-radius: 6px;
  background: var(--danger-soft); color: #912018;
  font-size: 12.5px; font-weight: 600;
}
.modal-actions {
  display: flex; justify-content: flex-end; gap: 10px;
  margin-top: 22px; padding-top: 16px; border-top: 1px solid var(--border);
}

/* ---------- 提示浮层 ---------- */
.toast-region {
  position: fixed; right: 18px; bottom: 18px; z-index: 60;
  display: flex; flex-direction: column; gap: 8px;
}
.toast {
  display: flex; align-items: flex-start; gap: 9px;
  width: 320px; padding: 12px 14px;
  background: #2a1408; color: #ffd7cf;
  border-left: 3px solid var(--danger); border-radius: 8px;
  box-shadow: 0 10px 30px rgba(2, 12, 27, .35);
  font-size: 12.5px; line-height: 1.5;
  animation: slide-in .25s ease;
}
.toast .ic { margin-top: 1px; color: #fda29b; }
.toast strong { display: block; margin-bottom: 2px; font-size: 12px; }
.toast.info-toast { background: #0e2a4d; color: #cfe4ff; border-left-color: var(--accent); }
.toast.info-toast .ic { color: #84b4ff; }
.toast.out { opacity: 0; transform: translateY(6px); transition: all .3s; }
@keyframes slide-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* 滚动条 */
::-webkit-scrollbar { width: 9px; }
::-webkit-scrollbar-thumb { background: #c9d2dd; border-radius: 8px; border: 2px solid var(--bg); }
::-webkit-scrollbar-track { background: transparent; }

